package com.lexiscan.analysis; import com.lexiscan.document.Document; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*;
@Entity @Table(name="analysis_results") @Getter @Setter @NoArgsConstructor public class AnalysisResult { @Id private UUID id=UUID.randomUUID(); @OneToOne(optional=false) @JoinColumn(name="document_id") private Document document; @Column(columnDefinition="TEXT") private String summary; @Column(name="overall_risk_score") private int overallRiskScore; @Column(name="overall_risk_level") private String overallRiskLevel; @Column(name="key_entities",columnDefinition="TEXT") private String keyEntities; @Column(name="clause_count") private int clauseCount; @Column(name="high_risk_count") private int highRiskCount; @Column(name="medium_risk_count") private int mediumRiskCount; @Column(name="created_at") private Instant createdAt=Instant.now(); }
